{"implementation":"def solve(case):
    text = case['text']
    passes = case['passes']
    max_rounds = case['max_rounds']
    applications = []
    fixed_point = False
    for _ in range(max_rounds):
        changed_this_round = False
        for p in passes:
            old, new = p['old'], p['new']
            if old in text:
                text = text.replace(old, new)
                changed_this_round = True
                applications.append(p['name'])
        if not changed_this_round:
            fixed_point = True
            break
    return {'applications': applications, 'fixed_point': fixed_point, 'text': text}
"}
